package main

const jsOnboard = `
function openReview(review){currentReview=review;const box=$("review-content");box.replaceChildren();const name=field(box,"Provider 名稱","text",review.provider.name);name.name="name";box.append(el("p",review.provider.base_url),el("p","Adapter："+review.provider.config.adapter+" · "+(review.catalog_verified?"Catalog 已取得":"Catalog 未確認")),el("p","尚未確認："+(review.unknown_fields||[]).join("、")));(review.endpoint_profiles||[]).forEach(p=>box.append(el("p",p.operation+" · "+p.url)));review.models.forEach(id=>{const label=el("label",id,"check"),input=el("input");input.type="checkbox";input.name="model";input.value=id;label.prepend(input);box.append(label);});action(box,"重試資料檢查",async()=>{const value=await submit("/onboarding/retry",{id:review.id});openReview(value);});if(!$("review").open)$("review").showModal();}
function bindOnboarding(){
 $("onboarding-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.target,button=f.querySelector("button"),v=data(f);button.disabled=true;try{const config={adapter:v.adapter,auth_mode:v.auth_mode,auth_header:v.auth_header,auth_query:v.auth_query,auth_prefix:v.auth_prefix,website:v.website,requires_daily_checkin:!!v.checkin_url,checkin_url:v.checkin_url,endpoints:v.chat_path?{CHAT_COMPLETIONS:v.chat_path}:{}};const credentials=[{label:"主要 Key",secret:v.secret,role:"INFERENCE",group:v.group,auth_fields:v.auth_fields?JSON.parse(v.auth_fields):[]}];if(v.pat)credentials.push({label:"帳戶 PAT",secret:v.pat,role:"ACCOUNT_PAT"});const review=await submit("/onboarding/preview",{mode:v.mode||"QUICK",provider:{name:v.name,base_url:v.base_url,auth_mode:v.auth_mode,config},account:{label:v.account_label},credentials,endpoint_profiles:v.endpoint_profiles?JSON.parse(v.endpoint_profiles):[],model_ids:(v.model_id||"").split(",").map(id=>id.trim()).filter(Boolean),group:v.group,endpoint:v.endpoint||"CHAT_COMPLETIONS"});f.elements.secret.value="";f.elements.pat.value="";f.elements.auth_fields.value="";openReview(review);}catch(e){notice(e.message,true);}finally{button.disabled=false;}});
 $("review-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.target,selected_model_ids=[...f.querySelectorAll('input[name="model"]:checked')].map(n=>n.value);if(!selected_model_ids.length){notice("選擇至少一個要加入的模型",true);return;}try{await submit("/onboarding/confirm",{id:currentReview.id,confirm:true,name:f.elements.name.value,selected_model_ids});$("review").close();await refresh();notice("Provider 與模型已加入");}catch(e){notice(e.message,true);}});
 $("import-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.target;try{const results=await submit("/onboarding/import",JSON.parse(f.elements.json.value));f.elements.json.value="";$("onboarding-list").replaceChildren();results.forEach(r=>{if(r.review)item($("onboarding-list"),r.review.provider.name,"待確認",()=>openReview(r.review));else item($("onboarding-list"),"項目 "+r.index,r.status);});notice("匯入清單已建立，逐項確認即可加入");}catch(e){notice(e.message,true);}});
}
`
